INSERT INTO workout_activities (id,name,category,definition) VALUES ('a1','Goblet Squat','strength','{"id":"a1","name":"Goblet Squat","category":"strength","focus":"quadriceps, glutes","equipment":"dumbbell","movement":"squat","tracking":"load","instructions":"Hold one dumbbell vertically at your chest. Feet shoulder-width, sit hips back and down, chest tall. Knees track over toes. Barbell option: front squat or back squat with the bar racked — same tempo, same rep range, don''t chase heavy weight here.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set.","schemaVersion":2,"bodyParts":["legs","glutes"],"primaryMuscles":["quadriceps","glutes"],"secondaryMuscles":[],"equipmentTags":["dumbbells"],"experienceLevels":["beginner","experienced"],"goals":["general_fitness","muscle_gain","strength","muscular_endurance","weight_management"],"measurements":[{"key":"sets","scope":"activity","unit":"sets","derived":true,"required":true,"min":1,"max":50,"integer":true},{"key":"reps","scope":"set","unit":"reps","required":true,"min":1,"max":10000,"integer":true},{"key":"weightKg","scope":"set","unit":"kg","required":true,"min":0,"max":2000,"integer":false}],"guidance":{"general_fitness":{"beginner":{"goal":"general_fitness","experience":"beginner","kind":"editable_starting_point","sets":[1,2],"reps":[8,12],"restSeconds":[60,120],"suggestedWeightKg":null,"weightMethod":"calibrate_to_target_reps","loadInstruction":"Start with a light load you can control throughout the target range. Aim to finish with about 2–3 good repetitions still possible. Record the actual load; adjust next time based on performance.","genderAdjustment":false,"sourceIds":["acsm-2026"],"rationale":"App starting defaults, not a personalized prescription. Adjust for ability, technique, equipment and recovery."},"experienced":{"goal":"general_fitness","experience":"experienced","kind":"editable_st