INSERT INTO workout_activities (id,name,category,definition) VALUES ('a3','Push-up (knees if needed)','strength','{"id":"a3","name":"Push-up (knees if needed)","category":"strength","focus":"chest, triceps","equipment":"bodyweight","movement":"push","tracking":"reps","instructions":"Hands under shoulders, body in a straight line. Drop knees to the floor if a full push-up is too hard. This is your main chest builder — form matters more than the version.","loadConvention":"Record repetitions or seconds; bodyweight is not counted as external load.","schemaVersion":2,"bodyParts":["chest","triceps"],"primaryMuscles":["chest","triceps"],"secondaryMuscles":[],"equipmentTags":["bodyweight"],"experienceLevels":["beginner","experienced"],"goals":["general_fitness","muscle_gain","strength","muscular_endurance","weight_management"],"measurements":[{"key":"sets","scope":"activity","unit":"sets","derived":true,"required":true,"min":1,"max":50,"integer":true},{"key":"reps","scope":"set","unit":"reps","required":true,"min":1,"max":10000,"integer":true}],"guidance":{"general_fitness":{"beginner":{"goal":"general_fitness","experience":"beginner","kind":"editable_starting_point","sets":[1,2],"reps":[8,12],"restSeconds":[60,120],"suggestedWeightKg":null,"weightMethod":"not_applicable","loadInstruction":"Choose a variation that lets you complete the target with control.","genderAdjustment":false,"sourceIds":["acsm-2026"],"rationale":"App starting defaults, not a personalized prescription. Adjust for ability, technique, equipment and recovery."},"experienced":{"goal":"general_fitness","experience":"experienced","kind":"editable_starting_point","sets":[2,3],"reps":[8,12],"restSeconds":[60,120],"suggestedWeightKg":null,"weightMethod":"not_applicable","loadInstruction":"Choose a variation that lets you complete the target with control.","genderAdjustment":false,"sourceIds":["acsm-2026"],"rationale":"App starting defaults, not a personalized prescription. Adjust for ability, technique, equip