INSERT INTO workout_activities (id,name,category,definition) VALUES ('b1','Reverse Lunge (dumbbells)','strength','{"id":"b1","name":"Reverse Lunge (dumbbells)","category":"strength","focus":"quadriceps, glutes","equipment":"dumbbells","movement":"lunge","tracking":"load","instructions":"Dumbbells at your sides, step back and lower until both knees hit ~90°. Push through the front heel to return.","loadConvention":"Total external load moved in each repetition. For two dumbbells, enter their combined weight. For unilateral exercises, record each side as its own set.","schemaVersion":2,"bodyParts":["legs","glutes"],"primaryMuscles":["quadriceps","glutes"],"secondaryMuscles":[],"equipmentTags":["dumbbells"],"experienceLevels":["beginner","experienced"],"goals":["general_fitness","muscle_gain","strength","muscular_endurance","weight_management"],"measurements":[{"key":"sets","scope":"activity","unit":"sets","derived":true,"required":true,"min":1,"max":50,"integer":true},{"key":"reps","scope":"set","unit":"reps","required":true,"min":1,"max":10000,"integer":true},{"key":"weightKg","scope":"set","unit":"kg","required":true,"min":0,"max":2000,"integer":false}],"guidance":{"general_fitness":{"beginner":{"goal":"general_fitness","experience":"beginner","kind":"editable_starting_point","sets":[1,2],"reps":[8,12],"restSeconds":[60,120],"suggestedWeightKg":null,"weightMethod":"calibrate_to_target_reps","loadInstruction":"Start with a light load you can control throughout the target range. Aim to finish with about 2–3 good repetitions still possible. Record the actual load; adjust next time based on performance.","genderAdjustment":false,"sourceIds":["acsm-2026"],"rationale":"App starting defaults, not a personalized prescription. Adjust for ability, technique, equipment and recovery."},"experienced":{"goal":"general_fitness","experience":"experienced","kind":"editable_starting_point","sets":[2,3],"reps":[8,12],"restSeconds":[60,120],"suggestedWeightKg":null,"weightMethod":"calib